-- DJ Ivo's target_id — public.profiles.id where display_name = 'ivaylotsachev'.
insert into public.profile_reviews (reviewer_id, target_id, criteria, body, created_at)
values
('7a386919-ecce-49e5-969d-d6b8fd1cb05d', '038a4499-20d1-46b1-a13e-aff5ad16f4c3', jsonb_build_object('mixing',5,'trackSelection',5,'crowdReading',5,'stagePresence',4), 'Best set I''ve heard all year, the transitions were seamless!', now() - interval '1 day'),
('4e062964-e7fd-4ed1-9921-153a4082f55b', '038a4499-20d1-46b1-a13e-aff5ad16f4c3', jsonb_build_object('mixing',4,'trackSelection',4,'crowdReading',5,'stagePresence',4), 'Great energy on the decks, would love a longer set next time.', now() - interval '2 days'),
('becbc7c8-6a31-4725-81dc-a2eb8c659ac7', '038a4499-20d1-46b1-a13e-aff5ad16f4c3', jsonb_build_object('mixing',5,'trackSelection',3,'crowdReading',4,'stagePresence',5), 'Incredible stage presence but the track selection felt a bit repetitive.', now() - interval '3 days'),
('83c3fc16-8ebd-45a4-bde9-9a42f1c189d5', '038a4499-20d1-46b1-a13e-aff5ad16f4c3', jsonb_build_object('mixing',3,'trackSelection',4,'crowdReading',3,'stagePresence',3), 'Solid but nothing groundbreaking.', now() - interval '4 days'),
('8915625b-dead-4e08-96fc-fb6f3a9539b4', '038a4499-20d1-46b1-a13e-aff5ad16f4c3', jsonb_build_object('mixing',5,'trackSelection',5,'crowdReading',5,'stagePresence',5), 'Absolute legend, book him again!', now() - interval '5 days'),
('24feee54-4ca8-4fa1-88e5-5dba47b47cb7', '038a4499-20d1-46b1-a13e-aff5ad16f4c3', jsonb_build_object('mixing',4,'trackSelection',5,'crowdReading',4,'stagePresence',4), 'Loved the track picks, felt like a proper journey.', now() - interval '6 days'),
