('b75a14d1-7c84-4fc2-b67d-3962595e5db0', '038a4499-20d1-46b1-a13e-aff5ad16f4c3', jsonb_build_object('mixing',5,'trackSelection',4,'crowdReading',5,'stagePresence',5), 'Packed the dancefloor the entire night!', now() - interval '8 days'),
